package com.nexus.domain; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="audit_logs",indexes=@Index(columnList="incident_id")) public class Audit{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="incident_id") public Long incidentId; public Instant at; public String actor,action,previousState,newState; @Column(length=16000) public String detail; public boolean privateEntry; protected Audit(){} public Audit(Long i,Instant at,String actor,String action,String old,String next,String detail,boolean priv){incidentId=i;this.at=at;this.actor=actor;this.action=action;previousState=old;newState=next;this.detail=detail;privateEntry=priv;}}
